  values (p_restaurant_id, v_cat, 'Croquetas de jamón ibérico', 'Iberian ham croquettes', 'Cremosas, hechas en casa cada mañana.', 'Creamy, made in house every morning.', 600, array['gluten','milk','eggs']::text[], '[{"id":"size","name_es":"Tamaño","name_en":"Size","required":true,"multi":false,"choices":[{"id":"half","name_es":"Media ración (4 uds)","name_en":"Half portion (4 pcs)","price_cents":0},{"id":"full","name_es":"Ración (8 uds)","name_en":"Full portion (8 pcs)","price_cents":450}]}]'::jsonb, 0, 'https://images.unsplash.com/photo-1767974963436-2208b3553561?auto=format&fit=crop&w=900&q=80', true);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Patatas bravas', 'Patatas bravas', 'Patata frita con nuestra salsa brava.', 'Fried potatoes with our spicy brava sauce.', 550, array['eggs']::text[], '[{"id":"sauce","name_es":"Salsa","name_en":"Sauce","required":true,"multi":false,"choices":[{"id":"brava","name_es":"Brava picante","name_en":"Spicy brava","price_cents":0},{"id":"alioli","name_es":"Alioli","name_en":"Garlic alioli","price_cents":0},{"id":"mix","name_es":"Mitad y mitad","name_en":"Half and half","price_cents":0}]}]'::jsonb, 1, 'https://images.unsplash.com/photo-1565599837634-134bc3aadce8?auto=format&fit=crop&w=900&q=80', true);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Pimientos de Padrón', 'Padrón peppers', 'Unos pican y otros no.', 'Some are hot, some are not.', 600, array[]::text[], '[]'::jsonb, 2, null, false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Pan con tomate', 'Bread with tomato', 'Pan tostado, tomate rallado y aceite de oliva virgen extra.', 'Toasted bread, grated tomato and extra virgin olive oil.', 350, array['gluten']::text[], '[{"id":"extras","name_es":"Extras","name_en":"Extras","required":false,"multi":true,"choices":[{"id":"ham","name_es":"Jamón ibérico","name_en":"Iberian ham","price_cents":300},{"id":"anchovy","name_es":"Anchoas","name_en":"Anchovies","price_cents":250}]}]'::jsonb, 3, null, false);
  insert into public.categories (restaurant_id, name_es, name_en, station, sort)
  values (p_restaurant_id, 'Platos', 'Mains', 'kitchen', 1) returning id into v_cat;
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Tortilla de patatas', 'Spanish omelette', 'La de toda la vida.', 'Classic potato omelette.', 700, array['eggs']::text[], '[{"id":"style","name_es":"Punto","name_en":"How cooked","required":true,"multi":false,"choices":[{"id":"runny","name_es":"Jugosa","name_en":"Runny","price_cents":0},{"id":"done","name_es":"Hecha","name_en":"Well done","price_cents":0}]},{"id":"onion","name_es":"Cebolla","name_en":"Onion","required":true,"multi":false,"choices":[{"id":"with","name_es":"Con cebolla","name_en":"With onion","price_cents":0},{"id":"without","name_es":"Sin cebolla","name_en":"Without onion","price_cents":0}]}]'::jsonb, 0, null, false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Pulpo a la gallega', 'Galician-style octopus', 'Con patata cocida, pimentón y aceite.', 'With boiled potato, paprika and olive oil.', 1650, array['molluscs']::text[], '[]'::jsonb, 1, 'https://images.unsplash.com/photo-1531890820402-2a683fbfd30c?auto=format&fit=crop&w=900&q=80', true);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Gambas al ajillo', 'Garlic prawns', 'En cazuela de barro, con guindilla.', 'Sizzling in a clay pot with chilli.', 1200, array['crustaceans']::text[], '[]'::jsonb, 2, 'https://images.unsplash.com/photo-1788462613187-b10c1ac2ea60?auto=format&fit=crop&w=900&q=80', false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Secreto ibérico', 'Iberian pork secreto', 'A la brasa, con sal en escamas.', 'Chargrilled, with flaky salt.', 1500, array[]::text[], '[{"id":"side","name_es":"Guarnición","name_en":"Side","required":true,"multi":false,"choices":[{"id":"fries","name_es":"Patatas fritas","name_en":"Fries","price_cents":0},{"id":"salad","name_es":"Ensalada","name_en":"Salad","price_cents":0},{"id":"padron","name_es":"Pimientos de Padrón","name_en":"Padrón peppers","price_cents":150}]}]'::jsonb, 3, null, false);
  insert into public.categories (restaurant_id, name_es, name_en, station, sort)
  values (p_restaurant_id, 'Postres', 'Desserts', 'kitchen', 2) returning id into v_cat;
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Tarta de queso', 'Baked cheesecake', 'Cremosa por dentro.', 'Soft and creamy in the middle.', 600, array['milk','eggs','gluten']::text[], '[]'::jsonb, 0, 'https://images.unsplash.com/photo-1759303380841-55c09244fd2b?auto=format&fit=crop&w=900&q=80', true);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Churros con chocolate', 'Churros with hot chocolate', '', '', 550, array['gluten','milk']::text[], '[]'::jsonb, 1, 'https://images.unsplash.com/photo-1515579171902-e0c5f918b32b?auto=format&fit=crop&w=900&q=80', false);
  insert into public.categories (restaurant_id, name_es, name_en, station, sort)
