  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Cerveza de barril', 'Draught beer', '', '', 250, array['gluten']::text[], '[{"id":"size","name_es":"Tamaño","name_en":"Size","required":true,"multi":false,"choices":[{"id":"cana","name_es":"Caña (20 cl)","name_en":"Small (20 cl)","price_cents":0},{"id":"doble","name_es":"Doble (40 cl)","name_en":"Large (40 cl)","price_cents":150}]}]'::jsonb, 0, 'https://images.unsplash.com/photo-1608270586620-248524c67de9?auto=format&fit=crop&w=900&q=80', false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Vermut de grifo', 'House vermouth', 'Con hielo y naranja.', 'With ice and orange.', 350, array['sulphites']::text[], '[]'::jsonb, 1, 'https://images.unsplash.com/photo-1615830783066-26a99bc9d959?auto=format&fit=crop&w=900&q=80', false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Vino tinto (copa)', 'Red wine (glass)', '', '', 380, array['sulphites']::text[], '[{"id":"wine","name_es":"Vino","name_en":"Wine","required":true,"multi":false,"choices":[{"id":"rioja","name_es":"Rioja crianza","name_en":"Rioja crianza","price_cents":0},{"id":"ribera","name_es":"Ribera del Duero","name_en":"Ribera del Duero","price_cents":70}]}]'::jsonb, 2, 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?auto=format&fit=crop&w=900&q=80', false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Tinto de verano', 'Tinto de verano', 'Vino tinto con gaseosa.', 'Red wine with lemon soda.', 350, array['sulphites']::text[], '[]'::jsonb, 3, null, false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Agua mineral', 'Mineral water', '', '', 200, array[]::text[], '[{"id":"type","name_es":"Tipo","name_en":"Type","required":true,"multi":false,"choices":[{"id":"still","name_es":"Sin gas","name_en":"Still","price_cents":0},{"id":"sparkling","name_es":"Con gas","name_en":"Sparkling","price_cents":30}]}]'::jsonb, 4, null, false);
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Refresco', 'Soft drink', '', '', 280, array[]::text[], '[{"id":"drink","name_es":"Elige","name_en":"Choose","required":true,"multi":false,"choices":[{"id":"cola","name_es":"Cola","name_en":"Cola","price_cents":0},{"id":"cola-zero","name_es":"Cola zero","name_en":"Cola zero","price_cents":0},{"id":"orange","name_es":"Naranja","name_en":"Orange","price_cents":0},{"id":"lemon","name_es":"Limón","name_en":"Lemon","price_cents":0}]}]'::jsonb, 5, null, false);
  insert into public.categories (restaurant_id, name_es, name_en, station, sort)
  values (p_restaurant_id, 'Cafés', 'Coffee', 'bar', 4) returning id into v_cat;
  insert into public.items (restaurant_id, category_id, name_es, name_en, desc_es, desc_en, price_cents, allergens, options, sort, image_url, featured)
  values (p_restaurant_id, v_cat, 'Café', 'Coffee', '', '', 180, array['milk']::text[], '[{"id":"type","name_es":"Tipo","name_en":"Type","required":true,"multi":false,"choices":[{"id":"solo","name_es":"Solo","name_en":"Espresso","price_cents":0},{"id":"cortado","name_es":"Cortado","name_en":"Cortado","price_cents":0},{"id":"leche","name_es":"Con leche","name_en":"White coffee","price_cents":30}]},{"id":"milk","name_es":"Leche","name_en":"Milk","required":false,"multi":false,"choices":[{"id":"whole","name_es":"Entera","name_en":"Whole","price_cents":0},{"id":"skimmed","name_es":"Desnatada","name_en":"Skimmed","price_cents":0},{"id":"oat","name_es":"De avena","name_en":"Oat","price_cents":40}]}]'::jsonb, 0, null, false);
  update public.restaurants set cover_url = coalesce(cover_url, 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1600&q=80') where id = p_restaurant_id;
  if not exists (select 1 from public.dining_tables where restaurant_id = p_restaurant_id) then
    insert into public.dining_tables (restaurant_id, label, sort)
    select p_restaurant_id, t.label, t.ord::int - 1 from unnest(array['Mesa 1', 'Mesa 2', 'Mesa 3', 'Mesa 4', 'Mesa 5', 'Mesa 6', 'Mesa 7', 'Mesa 8', 'Terraza 1', 'Terraza 2', 'Terraza 3', 'Terraza 4', 'Barra']) with ordinality as t(label, ord);
  end if;
end $$;

revoke execute on function public.seed_sample_menu(uuid) from public, anon, authenticated;
